package com.vlesscardvpn.core
import okio.ByteString.Companion.decodeBase64

/** Vendored KaringX rule data; pinned snapshot, never a remote executable/config import.
 * Exact domains and suffixes retain their different semantics. GeoIP is approximate.
 */
object KaringRuData {
    const val REVISION = "2eddd3aa684b50372fe5996378d49158ec1d5eb6"
    const val DOMAINS_SHA256 = "c65aa93784067714322a6e91f0cb8e9eb22cd0b5ef6721bd6a731c643645773a"
    const val IPS_SHA256 = "a129202eb5fb2e400572845f5363d18f9d1d001c7802eb0dd71439b188029c40"
    private fun unpack(text: String): List<String> = java.util.zip.GZIPInputStream(
        java.io.ByteArrayInputStream(requireNotNull(text.decodeBase64()).toByteArray()))
        .bufferedReader(Charsets.UTF_8).use { it.readLines().filter(String::isNotBlank) }
    val exact: List<String> by lazy { unpack("") }
    val suffix: List<String> by lazy { unpack("") }
    val ipv4: List<String> by lazy { unpack("") }
    val ipv6: List<String> by lazy { unpack("") }
}
